def largestSquareTank(heights):
    l, r = 0, len(heights) - 1
    best = 0
    while l < r:
        side = min(heights[l], heights[r], r - l)
        if side > best:
            best = side
        if heights[l] <= heights[r]:
            l += 1
        else:
            r -= 1
    return best * best
